function UISystemGuideTipsBoard:Update()
    --if not self.isActive then
    --    return
    --end
    if Utils.TouchCount() > 0 and not self.close then
        if KCookie.Get("QTEEnd") == 1 then return end
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.Container, position,
                    UIModule.RootCanvas.canvas.worldCamera)
            if isInRect then
                self.close = true
                --EasyTouch.SetEnableUIDetection(self.uiDetection)
                --if self.__animatorResetComplete then
                --    Events.RemoveListener(Constants.EventNames.MainHomeCameraAnimatorResetComplete, self.__animatorResetComplete)
                --    self.__animatorResetComplete = nil
                --end
                ---不在区域中
                KTool.SafeDelete(self.controller.gameObject, true)
            end
        end
    end
end

